// cube-agent/dist/mcp/server.js
var createMcpServer = () => new MCPServer({
  name: "My Server",
  version: "1.0.0",
  description: "A server that provides weather data and agent capabilities",
  instructions: "Use the available tools to help users with weather information and data processing tasks.",
  tools: {
    ask_user: cubeAskUserTool,
    taskWriteTool,
    taskCheckTool,
    taskCompleteTool,
    taskUpdateTool
  }
});

// cube-agent/dist/bootstrap.js
var createCubeMastra = async (home, workspace, config3) => {
  const logging = await createCubeLogger(home);
  const agent = await createCubeAgent(home, workspace, config3, logging.logger);
  const controller = await createCubeController(agent, workspace);
  const mcpServer2 = createMcpServer();
  const mastra = new Mastra({
    agents: { cubeAgent: agent },
    agentControllers: { cubeController: controller },
    logger: logging.logger,
    loggerOptions: {
      correlation: true,
      export: false
    },
    storage: new LibSQLStore({
      id: "cube-storage",
      url: `file:${home.getMemoryDbPath()}`
    }),
    mcpServers: {
      myServer: mcpServer2
    },
    observability: new Observability({
      configs: {
        default: {
          serviceName: "cube-agent",
          exporters: [new MastraStorageExporter()]
        }
      }
    })
  });
  let shutdownPromise;
  return {
    agent,
    controller,
    mastra,
    logger: logging.logger,
    shutdown: () => {
      shutdownPromise ??= (async () => {
        try {
          await mastra.shutdown();
        } finally {
          await logging.close();
        }
      })();
      return shutdownPromise;
    }
  };
};

